create extension if not exists pgcrypto;
create type public.user_role as enum ('student','faculty','admin');
create type public.material_status as enum ('draft','published','archived');
create table public.colleges(id uuid primary key default gen_random_uuid(),name_ar text not null,name_en text,code text unique not null,created_at timestamptz default now());
create table public.departments(id uuid primary key default gen_random_uuid(),college_id uuid not null references public.colleges on delete cascade,name_ar text not null,name_en text,code text unique not null,created_at timestamptz default now());
create table public.profiles(id uuid primary key references auth.users on delete cascade,full_name text not null,university_id text unique,role public.user_role not null default 'student',college_id uuid references public.colleges,department_id uuid references public.departments,is_active boolean not null default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.courses(id uuid primary key default gen_random_uuid(),department_id uuid references public.departments,code text not null,title text not null,description text,term text not null,academic_year text not null,is_published boolean not null default false,created_by uuid references public.profiles,created_at timestamptz default now(),unique(code,term,academic_year));
create table public.course_staff(course_id uuid references public.courses on delete cascade,profile_id uuid references public.profiles on delete cascade,primary key(course_id,profile_id));
create table public.enrollments(course_id uuid references public.courses on delete cascade,student_id uuid references public.profiles on delete cascade,status text not null default 'active',enrolled_at timestamptz default now(),primary key(course_id,student_id));
create table public.materials(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses on delete cascade,title text not null,description text,material_type text not null default 'document',file_path text not null,file_name text not null,mime_type text,size_bytes bigint,status public.material_status not null default 'draft',uploaded_by uuid not null references public.profiles,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.announcements(id uuid primary key default gen_random_uuid(),course_id uuid references public.courses on delete cascade,title text not null,body text not null,published_by uuid references public.profiles,published_at timestamptz default now());
create table public.assignments(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses on delete cascade,title text not null,instructions text,due_at timestamptz,max_grade numeric(6,2) default 100,created_by uuid references public.profiles,created_at timestamptz default now());
create table public.submissions(id uuid primary key default gen_random_uuid(),assignment_id uuid not null references public.assignments on delete cascade,student_id uuid not null references public.profiles on delete cascade,file_path text,notes text,submitted_at timestamptz default now(),grade numeric(6,2),feedback text,graded_by uuid references public.profiles,unique(assignment_id,student_id));
create or replace function public.current_role() returns public.user_role language sql stable security definer set search_path=public as $$select role from public.profiles where id=auth.uid()$$;
create or replace function public.teaches_course(course uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.course_staff where course_id=course and profile_id=auth.uid()) or public.current_role()='admin'$$;
alter table public.profiles enable row level security;alter table public.colleges enable row level security;alter table public.departments enable row level security;alter table public.courses enable row level security;alter table public.course_staff enable row level security;alter table public.enrollments enable row level security;alter table public.materials enable row level security;alter table public.announcements enable row level security;alter table public.assignments enable row level security;alter table public.submissions enable row level security;
create policy "authenticated reads structure" on public.colleges for select to authenticated using(true);create policy "authenticated reads departments" on public.departments for select to authenticated using(true);
create policy "profile reads self" on public.profiles for select to authenticated using(id=auth.uid() or public.current_role()='admin');create policy "profile updates self" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "students read enrolled courses" on public.courses for select to authenticated using(public.current_role()='admin' or public.teaches_course(id) or exists(select 1 from public.enrollments e where e.course_id=id and e.student_id=auth.uid()));create policy "staff manage courses" on public.courses for all to authenticated using(public.current_role()='admin' or public.teaches_course(id)) with check(public.current_role() in ('faculty','admin'));
create policy "read own course staff" on public.course_staff for select to authenticated using(profile_id=auth.uid() or public.current_role()='admin');create policy "read relevant enrollments" on public.enrollments for select to authenticated using(student_id=auth.uid() or public.teaches_course(course_id));
create policy "read published materials" on public.materials for select to authenticated using((status='published' and exists(select 1 from public.enrollments e where e.course_id=materials.course_id and e.student_id=auth.uid())) or public.teaches_course(course_id));create policy "staff manage materials" on public.materials for all to authenticated using(public.teaches_course(course_id)) with check(public.teaches_course(course_id) and uploaded_by=auth.uid());
create policy "read relevant announcements" on public.announcements for select to authenticated using(course_id is null or public.teaches_course(course_id) or exists(select 1 from public.enrollments e where e.course_id=announcements.course_id and e.student_id=auth.uid()));create policy "staff manage announcements" on public.announcements for all to authenticated using(public.current_role()='admin' or public.teaches_course(course_id)) with check(public.current_role()='admin' or public.teaches_course(course_id));
create policy "read relevant assignments" on public.assignments for select to authenticated using(public.teaches_course(course_id) or exists(select 1 from public.enrollments e where e.course_id=assignments.course_id and e.student_id=auth.uid()));create policy "staff manage assignments" on public.assignments for all to authenticated using(public.teaches_course(course_id)) with check(public.teaches_course(course_id));
create policy "students manage own submissions" on public.submissions for all to authenticated using(student_id=auth.uid() or public.teaches_course((select course_id from public.assignments where id=assignment_id))) with check(student_id=auth.uid() or public.teaches_course((select course_id from public.assignments where id=assignment_id)));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('course-materials','course-materials',false,52428800,array['application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.presentationml.presentation']) on conflict(id) do nothing;
create policy "enrolled users read course files" on storage.objects for select to authenticated using(bucket_id='course-materials' and exists(select 1 from public.materials m where m.file_path=name and (public.teaches_course(m.course_id) or exists(select 1 from public.enrollments e where e.course_id=m.course_id and e.student_id=auth.uid()))));create policy "staff upload course files" on storage.objects for insert to authenticated with check(bucket_id='course-materials' and public.current_role() in ('faculty','admin'));create policy "staff update course files" on storage.objects for update to authenticated using(bucket_id='course-materials' and public.current_role() in ('faculty','admin'));create policy "staff delete course files" on storage.objects for delete to authenticated using(bucket_id='course-materials' and public.current_role() in ('faculty','admin'));
